module top_module(
  input clk,
  input reset,
  input [31:0] high,
  input [31:0] low,
  input [31:0] initial_value,
  input [8*6:1] mode,
  input [31:0] ph_tap,
  output reg cout
);reg [31:0] count;
  reg [31:0] output_shift_count;
  reg tmp_cout;
  reg first_rising_edge;
  reg clk_last_value;
  reg init;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      count <= 1;
      output_shift_count <= 1;
      tmp_cout <= 0;
      first_rising_edge <= 0;
    end else begin
      if (init !== 1'b1) begin
        clk_last_value <= 0;
        init <= 1'b1;
      end
      if (clk_last_value !== clk) begin
        if (mode == "   off") begin
          tmp_cout <= 0;
        end else if (mode == "bypass") begin
          tmp_cout <= clk;
          first_rising_edge <= 1;
        end else if (first_rising_edge == 0) begin
          if (clk == 1) begin
            if (output_shift_count == initial_value) begin
              tmp_cout <= clk;
              first_rising_edge <= 1;
            end else begin
              output_shift_count <= output_shift_count + 1;
            end
          end
        end else if (output_shift_count < initial_value) begin
          if (clk == 1) begin
            output_shift_count <= output_shift_count + 1;
          end
        end else begin
          count <= count + 1;
          if (mode == "  even" && (count == (high*2) + 1)) begin
            tmp_cout <= 0;
          end else if (mode == "   odd" && (count == (high*2))) begin
            tmp_cout <= 0;
          end else if (count == (high + low)*2 + 1) begin
            tmp_cout <= 1;
            count <= 1;
          end
        end
        clk_last_value <= clk;
      end
    end
    cout <= tmp_cout;
  end

endmodule

module top_module(
    Y ,
    A1,
    A2,
    B1
);// Module ports
    output Y ;
    input  A1;
    input  A2;
    input  B1;

    // Local signals
    wire and0_out  ;
    wire nor0_out_Y;

    //  Name  Output      Other arguments
    and and0 (and0_out  , A1, A2         );
    nor nor0 (nor0_out_Y, B1, and0_out   );
    assign Y = ~nor0_out_Y;

endmodule

