module top_module(
		DATA_IN, 
		pc_in, pc_out, pc_increment, 
		DATA_OUT, 
		clk
	);input[21:0] DATA_IN;
	input pc_in,pc_out,pc_increment,clk;

	output[31:0] DATA_OUT;
	reg[31:0] DATA_OUT;

	reg[21:0] PC;

	always @(posedge clk)
	begin
		if (pc_in) begin
			PC <= DATA_IN;
		end else if(pc_increment) begin
			PC <= PC+1;
		end
	end

	always @(*)
	begin
		if(pc_out) begin
			DATA_OUT[21:0] <= PC;
			DATA_OUT[31:22] <= 10'd0;
		end else begin
			DATA_OUT <= 32'bZ;
		end
	end

endmodule

