module fsm (
        input clk,
        input reset,
        input v,
        output reg y);parameter Q0=0, Q1=1, Q2=2;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= Q0;
		else 
			state <= next;


	always_comb begin
		case(state)
			Q0: next = v ? Q1 : Q2;
			Q1: next = v ? Q2 : Q0;
			Q2: next = v ? Q0 : Q1;
			default: next = 'x;
		endcase
	end

	assign y = (state == Q0 || state == Q1);

endmodule

