module top_module(
  input wire clk,
  input wire reset,
  input wire [15:0] tone_in,
  input wire [15:0] threshold,
  input wire [31:0] sample_rate,
  output wire [15:0] tone_out
);reg [31:0] phase_accumulator;
  reg [31:0] phase_step;
  reg [15:0] sine_table [0:255];
  reg [7:0] sine_index;
  reg [15:0] sine_value; // Changed from wire to reg

  // Goertzel algorithm
  reg [31:0] s_prev;
  reg [31:0] s_prev2;
  reg [31:0] coeff;
  reg [31:0] target_frequency;
  reg [31:0] power;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      s_prev <= 32'd0;
      s_prev2 <= 32'd0;
      target_frequency <= 32'd0;
      power <= 32'd0;
    end else begin
      s_prev <= (coeff * s_prev) - s_prev2 + tone_in;
      s_prev2 <= s_prev;
      target_frequency <= (sample_rate << 16) / (2 * 32'h3_1415);
      coeff <= (2 * 32'h3_1415 * target_frequency) >> 16;
      power <= (s_prev * s_prev) + (s_prev2 * s_prev2) - ((coeff * s_prev) * s_prev2);
    end
  end

  // Sine wave generation
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      phase_accumulator <= 32'd0;
      phase_step <= 32'd0;
    end else begin
      phase_accumulator <= phase_accumulator + phase_step;
      phase_step <= (power < threshold) ? target_frequency : 32'd0;
    end
  end

  always @(posedge clk) begin
    sine_index <= phase_accumulator[23:16];
    sine_value <= sine_table[sine_index];
  end

  // Sine table initialization
  integer i;
  initial begin
    for (i = 0; i < 256; i = i + 1) begin
      sine_table[i] = 16'h0000 + (16'h7FFF * $rtoi($sin(2 * 3.1415926 * i / 256)));
    end
  end

  assign tone_out = sine_value;

endmodule

