module top_module (
  input in1,
  input in2,
  input in3,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter T=0, U=1, V=2, W=3;

    always_comb begin
        case (state)
            T: next_state = (in1 && in2) ? U : V;
            U: next_state = in3 ? V : W;
            V: next_state = (in1 && !in2) ? W : T;
            W: next_state = (in1 || !in3) ? U : T;
        endcase
    end

    assign out = (state == U) || (state == W);

endmodule

