module top_module(
    input wire clk,
    input wire rst,

    output wire bck_o,
    output wire data_o,
    output wire lrck_o,

    input wire [1:0] ack_i,
    input wire [23:0] data_i,
    output wire [1:0] pop_o
);// Divide the input clock by 256 to generate the left-right clock output
reg [7:0] clk_counter;
always @(posedge clk) begin
    if (rst) begin
        clk_counter <= 0;
    end else begin
        clk_counter <= clk_counter + 1;
    end
end
wire lrck_int_o = ~clk_counter[7];
reg lrck_ff;
always @(posedge clk) begin
    lrck_ff <= lrck_int_o;
end
assign lrck_o = lrck_ff;

// Divide the input clock by 4 to generate the bit clock output
wire bck_int_o = clk_counter[1];
reg bck_ff;
always @(posedge clk) begin
    bck_ff <= bck_int_o;
end
assign bck_o = bck_ff;

// Synchronize the input data with the bit clock
reg [23:0] data_i_ff [1:0];
always @(posedge clk) begin
    if (rst) begin
        data_i_ff[0] <= 0;
        data_i_ff[1] <= 0;
    end else if (ack_i[0]) begin
        data_i_ff[0] <= data_i;
    end else if (ack_i[1]) begin
        data_i_ff[1] <= data_i;
    end
end

// Generate the data output by combining the selected input channel with a zero byte
reg [31:0] data_o_ff;
wire data_int_o = data_o_ff[31];
reg data_o_buf_ff;
always @(posedge clk) begin
    data_o_buf_ff <= data_int_o;
end
assign data_o = data_o_buf_ff;

wire chsel = clk_counter[7];
always @(posedge clk) begin
    if (clk_counter[6:0] == 7'h7f) begin
        data_o_ff <= {data_i_ff[chsel], 8'b0};
    end else if (clk_counter[1:0] == 2'b11) begin
        data_o_ff <= {data_o_ff[30:0], 1'b0};
    end
end

// Output the selected input channel on pop_o
assign pop_o = {~ack_i[1], ~ack_i[0]};

endmodule

