description:
Design a circuit that performs conditional left and right shifting on a 28-bit input. It takes shift values from two 8-bit inputs for left and right shifts and uses an enable signal for each operation. The module shifts `mux_4_output` to the left or right based on the enabled condition, while preserving the most significant bit and setting the least significant bit to 1 after the shift.
module top_module(clk,res,shift_left_bits,shift_right_bits,
  shift_left_en,shift_right_en,mux_4_output,out);

code:
module top_module(clk,res,shift_left_bits,shift_right_bits,
  shift_left_en,shift_right_en,mux_4_output,out);input clk,res,shift_left_en,shift_right_en;
  input [7:0] shift_left_bits,shift_right_bits;
  input [27:0] mux_4_output;
  output reg [27:0] out;

  always @(posedge clk) begin
    if(shift_right_en)
      out = mux_4_output >> shift_right_bits;
    else if(shift_left_en)
      out = mux_4_output << shift_left_bits;
    out[27] = mux_4_output[27];
    out[0] = 1;
  end
endmodule

