module top_module(
    input clk,
    input rst,
    input stall,
    input [31:0] me_memdata,
    input [4:0] me_td,
    input me_WREG,
    output reg [31:0] wb_memdata,
    output reg [4:0] wb_td,
    output reg wb_WREG
);reg [31:0] reg_file [31:0];

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset all registers
            integer i;
            for (i = 0; i < 32; i = i + 1) begin
                reg_file[i] <= 32'b0;
            end
        end else if (me_WREG) begin
            // Write to register file
            reg_file[me_td] <= me_memdata;
        end
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            wb_memdata <= 0;
            wb_td <= 0;
            wb_WREG <= 0;
        end else if (stall) begin
            wb_memdata <= 0;
            wb_td <= 0;
            wb_WREG <= 0;
        end else begin
            wb_memdata <= me_memdata;
            wb_td <= me_td;
            wb_WREG <= me_WREG;
        end
    end

endmodule

description:
Design a module that functions as a simple register interface for a FIFO (First-In, First-Out) timecode transmitter. This module has a 2-bit address space allowing for chip selection, a write operation to store 32-bit data when the chip is selected and writing is enabled, and a read operation that outputs the least significant 8 bits of the written data through `out_port`. The remaining 24 bits are retained in a buffer and can be read back. The module resets both the output data and buffer when the reset signal is asserted low, ensuring controlled initialization of the stored data.
module top_module(
  // inputs:
  address,
  chipselect,
  clk,
  reset_n,
  write_n,
  writedata,

  // outputs:
  out_port,
  readdata
);

