module top_module(
  input [n-1:0] data,
  input [log2_w-1:0] ctrl,
  input wr_en,
  input rst,
  output [m-1:0] ctrl_out
);// Define parameters
parameter n = 4; // number of data signals
parameter m = 2; // number of control signals
parameter w = 8; // number of bits in each control register

// Function to calculate log2
function integer log2;
  input integer value;
  begin
    log2 = 0;
    while (2**log2 < value) begin
      log2 = log2 + 1;
    end
  end
endfunction

// Calculate the number of bits required for ctrl
localparam log2_w = log2(w);

// Array of control registers
reg [w-1:0] control_registers [0:w-1]; // array of control registers
integer i;

// Write to the selected control register
always @(posedge wr_en) begin
  if (rst) begin
    for (i = 0; i < w; i = i + 1) begin
      control_registers[i] <= 0;
    end
  end else begin
    control_registers[ctrl] <= data;
  end
end

// Connect control outputs to the selected control register
assign ctrl_out = control_registers[ctrl];

endmodule

