    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);wire [3:0] xor_result;
    wire [3:0] and_result;
    wire [3:0] sum_result;

    assign xor_result = a ^ b;
    assign and_result = a & b;
    assign sum_result = xor_result ^ cin;

    assign sum = sum_result;
    assign cout = (and_result | (xor_result & cin)) ? 1'b1 : 1'b0;

