module top_module(
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] OUT,
    output OV,
    output CO
);wire [4:0] sum;
    wire [4:0] diff;
    wire [4:0] B_inv;

    assign B_inv = ~B + 1;

    assign sum = {1'b0, A} + {1'b0, B};
    assign diff = {1'b0, A} + {1'b1, B_inv};

    assign OUT = SUB ? diff[3:0] : sum[3:0];
    assign OV = SUB ? diff[4] ^ diff[3] : sum[4] ^ sum[3];
    assign CO = SUB ? ~diff[4] : sum[4];

endmodule

module top_module(
   input                     clk,
   input                     en,
   input [BITS-1:0]          data_a,
   input [BITS-1:0]          data_b,
   output reg [(BITS*2)-1:0] result,
   output                    done
   );parameter BITS = 16;

   localparam STATE_IDLE     = 0;
   localparam STATE_MULTIPLY = 1;

   reg                    state = STATE_IDLE;
   reg [$clog2(BITS)-1:0] mul_counter = 0;
   reg [BITS-1:0]         data_a_reg = 0;
   reg [(BITS*2)-1:0]     data_b_reg = 0;

   assign done = (STATE_IDLE == state) && !en;

   always @ (posedge clk) begin
      case (state)
         STATE_IDLE: begin
            if (en) begin
               mul_counter <= 0;
               data_a_reg <= data_a;
               data_b_reg <= { {BITS{1'b0}}, data_b };
               result <= 0;
               state <= STATE_MULTIPLY;
            end
         end
         STATE_MULTIPLY: begin
            if (mul_counter == BITS - 1) begin
               state <= STATE_IDLE;
            end else begin
               mul_counter <= mul_counter + 1;
            end
            data_a_reg <= data_a_reg >> 1;
            data_b_reg <= data_b_reg << 1;
            if (data_a_reg[0]) begin
               result <= result + data_b_reg;
            end
         end
      endcase
   end

endmodule

