description:
Design a clock delay buffer that generates an output clock signal (`clk_out`) with a frequency that is reduced by a factor of 250 after a reset condition. The module uses an internal counter incremented on every positive edge of the input clock (`clk_in`). When the counter reaches a specified value corresponding to a 5 ns delay, the output clock toggles, effectively creating a divided clock signal. If the reset signal is activated, the output clock and the counter are both reset to their initial states.
module top_module(
  input clk_in,
  input reset,
  output reg clk_out
);

code:
module top_module(
  input clk_in,
  input reset,
  output reg clk_out
);// Counter to count 5 ns
  reg [22:0] counter = 0;

  always @(posedge clk_in, posedge reset) begin
    if (reset) begin
      clk_out <= 1'b0;
      counter <= 0;
    end else begin
      if (counter == 23'd249) begin
        counter <= 0;
        clk_out <= ~clk_out;
      end else begin
        counter <= counter + 1;
      end
    end
  end

endmodule

