description:
Implement the Verilog module based on the following description.
Build a 4-bit binary counter with asynchronous active low reset signal and a load enable signal. When load is high, load the counter with the provided value.
// (1) reset_n: Resets the counter to 4'b0000 when low.
// (2) load: Enables the load operation when high.
// (3) load_val: The value to be loaded into the counter when load is high.
// (4) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input load,
    input [3:0] load_val,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input load,
    input [3:0] load_val,
    output reg [3:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else if (load) begin
            // Load operation: Load the counter with the provided value
            q <= load_val;
        end else begin
            // Binary counter: Increment by 1
            q <= q + 1;
        end
    end

endmodule

