  input        RAM_P0_WR_EN,
  input  [8:0] RAM_P1_ADDR,
  input        RAM_P1_CLK,
  input        RAM_P1_CLKS,
  output reg [31:0] RAM_P1_RD_DATA,
  input        RAM_P1_RD_EN,
  input        RAM_RME_af,
  input  [3:0] RAM_RM_af,
  input        RAM_TEST1_af
);reg [31:0] mem [511:0]; // 512 x 32-bit memory

  always @(posedge RAM_P0_CLK or posedge RAM_P0_CLKS) begin
    if (RAM_RME_af) begin
      if (RAM_RM_af == 1) begin
        // Asynchronous reset
        integer i;
        for (i = 0; i < 512; i = i + 1) begin
          mem[i] <= 32'b0;
        end
      end else if (RAM_RM_af == 2) begin
        // Synchronous reset
        if (RAM_P0_CLKS) begin
          integer i;
          for (i = 0; i < 512; i = i + 1) begin
            mem[i] <= 32'b0;
          end
        end
      end
    end else if (RAM_P0_WR_EN) begin
      // Write operation
      if (RAM_P0_WR_BE[0]) mem[RAM_P0_ADDR][7:0]   <= RAM_P0_WR_DATA[7:0];
      if (RAM_P0_WR_BE[1]) mem[RAM_P0_ADDR][15:8]  <= RAM_P0_WR_DATA[15:8];
      if (RAM_P0_WR_BE[2]) mem[RAM_P0_ADDR][23:16] <= RAM_P0_WR_DATA[23:16];
      if (RAM_P0_WR_BE[3]) mem[RAM_P0_ADDR][31:24] <= RAM_P0_WR_DATA[31:24];
    end
  end

  always @(posedge RAM_P1_CLK or posedge RAM_P1_CLKS) begin
    if (RAM_RME_af) begin
      if (RAM_RM_af == 1) begin
        // Asynchronous reset
        RAM_P1_RD_DATA <= 32'b0;
      end else if (RAM_RM_af == 2) begin
        // Synchronous reset
        if (RAM_P1_CLKS) begin
          RAM_P1_RD_DATA <= 32'b0;
        end
      end
    end else if (RAM_P1_RD_EN) begin
      // Read operation
      RAM_P1_RD_DATA <= mem[RAM_P1_ADDR];
    end
  end

endmodule

module top_module(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    input clk,     // Added clk input
    output reg [7:0] out
);always @(*) begin
    case(op)
        2'b00: out = a + b;
        2'b01: out = a - b;
        2'b10: out = a & b;
        2'b11: out = a | b;
        default: out = 8'b0; // Added default case to handle undefined op
    endcase
end

always @(posedge clk) begin
    // The out variable is updated on the positive edge of the clock
    // It should be assigned the value from the combinatorial logic above.
    out <= out; // Note: This can be changed if you want to latch based on combinational logic.
end

endmodule

