module top_module(
	CLK,
	RESETn,
	ADDR,
	DATA_IN,
	MEM_REQ,
	MEM_WRITE,
	DATA_OUT,
	MEM_ACK_OUT
);parameter MEM_DEPTH = 65536;
	parameter LC_MEM_DATA_WIDTH = 32;
	parameter LC_MEM_ADDR_WIDTH = 32;

	input 	CLK;
	input	RESETn;
	input	[LC_MEM_ADDR_WIDTH-1:0]	ADDR;
	input	[LC_MEM_DATA_WIDTH-1:0]	DATA_IN;
	input	MEM_REQ;
	input	MEM_WRITE;
	output	reg [LC_MEM_DATA_WIDTH-1:0]	DATA_OUT;
	output	reg	MEM_ACK_OUT;

	reg	 [LC_MEM_DATA_WIDTH-1:0] mem_array [0:MEM_DEPTH-1];
	reg	[1:0] fsm;
	wire	[(LC_MEM_ADDR_WIDTH-1):0] addr_equal = ADDR[(LC_MEM_ADDR_WIDTH-1):0];

	parameter IDLE = 2'b00;
	parameter CLEAR = 2'b01;
	parameter WRITE = 2'b10;
	parameter READ = 2'b11;

	always @ (posedge CLK or negedge RESETn)
	begin
		if (~RESETn)
		begin
			fsm <= IDLE;
			MEM_ACK_OUT <= 0;
			DATA_OUT <= 0;
		end
		else
		begin
			case (fsm)
				IDLE:
				begin
					if ((MEM_REQ) && (ADDR < MEM_DEPTH))
					begin
						if (MEM_WRITE)
							fsm <= WRITE;
						else
							fsm <= READ;
					end
				end

				WRITE:
				begin
					mem_array[addr_equal] <= DATA_IN;
					MEM_ACK_OUT <= 1;
					fsm <= CLEAR;
				end

				READ:
				begin
					DATA_OUT <= mem_array[addr_equal];
					MEM_ACK_OUT <= 1;
					fsm <= CLEAR;
				end

				CLEAR:
				begin
					if (~MEM_REQ)
					begin
						fsm <= IDLE;
						MEM_ACK_OUT <= 0;
					end
				end
			endcase
		end
	end

endmodule

module top_module(
  input clk,
  input rst,
  input [n-1:0] in,
  output reg [m-1:0] out // Changed from wire to reg
);parameter n = 4; // number of input samples
parameter m = 2; // number of output samples
parameter k = 3; // number of filter coefficients

reg [n-1:0] shift_reg [0:n-1]; // Corrected to make it an array
reg [m-1:0] output_reg;
reg [k-1:0] coeff_mem [0:k-1];

integer i, j;

initial begin
  // Initialize output register
  output_reg = 0;

  // Initialize filter coefficients
  coeff_mem[0] = 1;
  coeff_mem[1] = 2;
  coeff_mem[2] = 1;
end

always @(posedge clk) begin
  if (rst) begin
    // Reset shift register and output register to zero
    for (i = 0; i < n; i = i + 1) begin
      shift_reg[i] <= 0;
    end
    output_reg <= 0;
  end else begin
    // Shift in new input sample and shift out oldest input sample
    for (i = n-1; i > 0; i = i - 1) begin
      shift_reg[i] <= shift_reg[i-1];
    end
    shift_reg[0] <= in;

    // Compute weighted sum of previous k input samples using filter coefficients
    output_reg = 0;
    for (j = 0; j < k; j = j + 1) begin
      output_reg = output_reg + (shift_reg[j] * coeff_mem[j]);
    end

    // Output result of weighted sum as current output sample
    out <= output_reg; // No changes needed here
  end
end

endmodule

